def second(t):
    m=re.match(r"\s*Let('s|\s+\$|\s+the|\s+us|\s+[A-Za-z]+)?",t)
    if not m: return 'notLet'
    s=(m.group(1) or '').strip()
    if s=="'s": return "Let's"
    if s=='$': return 'Let $'
    if s in('the','us'): return 'Let '+s
    return 'Let word'
